import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

layer_norm_gelu_scale_source = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// Naive kernel that performs LayerNorm + GELU + scaling in one pass across (N, C, D, H, W).
// We assume we normalize across C (channel dimension) for each (N, D, H, W) location.
__global__ void layer_norm_gelu_scale_kernel(
    const float* __restrict__ x,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ out,
    const float eps,
    const float scaling_factor,
    const int N,
    const int C,
    const int D,
    const int H,
    const int W
) {
    int nDHW = blockIdx.x * blockDim.x + threadIdx.x;
    int totalDHW = N * D * H * W;
    if (nDHW >= totalDHW) {
        return;
    }

    // Map linear index back to (n, d, h, w)
    int w_idx = nDHW % W;
    int temp = nDHW / W;
    int h_idx = temp % H;
    temp /= H;
    int d_idx = temp % D;
    int n_idx = temp / D;

    // Compute mean and variance across channels
    float sum_val = 0.0f;
    float sum_sq_val = 0.0f;

    // Pointer offset
    int offset_base = ((n_idx * C * D + d_idx) * H + h_idx) * W + w_idx;

    // Accumulate sums
    for (int c = 0; c < C; c++) {
        float val = x[offset_base + c * D * H * W];
        sum_val += val;
        sum_sq_val += val * val;
    }

    float mean = sum_val / (float)C;
    float var = (sum_sq_val / (float)C) - (mean * mean);
    float inv_std = rsqrtf(var + eps);

    // Apply LN, then GELU, then scale
    for (int c = 0; c < C; c++) {
        float val = x[offset_base + c * D * H * W];
        // LayerNorm
        float normed = (val - mean) * inv_std;
        // Apply gamma and beta
        normed = gamma[c] * normed + beta[c];
        // GELU
        // Approximation: gelu(x) = 0.5 * x * (1 + tanh(sqrt(2/pi)*(x + 0.044715*x^3)))
        float gelu = 0.5f * normed * (1.0f + tanhf(0.7978845608f * normed
                              + 0.035677408136f * normed * normed * normed));
        // Scale
        gelu *= scaling_factor;
        out[offset_base + c * D * H * W] = gelu;
    }
}

torch::Tensor layer_norm_gelu_scale_cuda(
    torch::Tensor x,
    torch::Tensor gamma,
    torch::Tensor beta,
    double eps,
    double scaling_factor
) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(gamma.is_cuda(), "gamma must be a CUDA tensor");
    TORCH_CHECK(beta.is_cuda(), "beta must be a CUDA tensor");

    int N = x.size(0);
    int C = x.size(1);
    int D = x.size(2);
    int H = x.size(3);
    int W = x.size(4);

    auto out = torch::empty_like(x);

    int totalDHW = N * D * H * W;
    const int block_size = 256;
    const int grid_size = (totalDHW + block_size - 1) / block_size;

    layer_norm_gelu_scale_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        out.data_ptr<float>(),
        static_cast<float>(eps),
        static_cast<float>(scaling_factor),
        N, C, D, H, W
    );

    return out;
}
'''

layer_norm_gelu_scale_cpp_source = r"""
torch::Tensor layer_norm_gelu_scale_cuda(
    torch::Tensor x,
    torch::Tensor gamma,
    torch::Tensor beta,
    double eps,
    double scaling_factor
);
"""

# Compile the custom CUDA code for LN + GELU + scaling
layer_norm_gelu_scale = load_inline(
    name="layer_norm_gelu_scale",
    cpp_sources=layer_norm_gelu_scale_cpp_source,
    cuda_sources=layer_norm_gelu_scale_source,
    functions=["layer_norm_gelu_scale_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized model that replaces the layer normalization + GELU + scale with a custom CUDA kernel.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, bias=True, eps=1e-5, scaling_factor=1.0):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size,
                                                 stride=stride, padding=padding, bias=bias)
        self.eps = eps
        self.scaling_factor = scaling_factor
        # We use nn.Parameter for gamma and beta, similar to named parameters in nn.LayerNorm
        self.gamma = nn.Parameter(torch.ones(out_channels, dtype=torch.float))
        self.beta = nn.Parameter(torch.zeros(out_channels, dtype=torch.float))

    def forward(self, x):
        x = self.conv_transpose(x)
        # Use custom kernel for LN + GELU + scale
        x = layer_norm_gelu_scale.layer_norm_gelu_scale_cuda(
            x, self.gamma, self.beta, self.eps, self.scaling_factor
        )
        return x

